<?php
if(!function_exists('wc_get_product'))return;
update_option('blogname','Seleneith');update_option('blog_public',0);update_option('permalink_structure','/%postname%/');update_option('woocommerce_currency','USD');update_option('woocommerce_default_country','US:NY');update_option('woocommerce_calc_taxes','no');update_option('woocommerce_coming_soon','no');update_option('woocommerce_enable_guest_checkout','yes');
$path=WP_CONTENT_DIR.'/reference/necklaces.json';if(!file_exists($path))throw new RuntimeException('Missing reference/necklaces.json in wp-content.');
update_option('woocommerce_enable_myaccount_registration','yes');update_option('woocommerce_registration_generate_username','yes');update_option('woocommerce_registration_generate_password','no');update_option('woocommerce_enable_signup_and_login_from_checkout','yes');
$rows=json_decode(file_get_contents($path),true);$category=term_exists('Necklaces','product_cat');if(!$category)$category=wp_insert_term('Necklaces','product_cat');
foreach($rows as $index=>$row){$existing=get_page_by_path($row['handle'],OBJECT,'product');if($existing)continue;$p=new WC_Product_Simple();$p->set_name($row['title']);$p->set_slug($row['handle']);$p->set_status('publish');$p->set_regular_price($row['regular']?:$row['price']);if($row['regular']>$row['price'])$p->set_sale_price($row['price']);$p->set_stock_status($row['available']?'instock':'outofstock');if(isset($row['stock_quantity'])){$p->set_manage_stock(true);$p->set_stock_quantity((int)$row['stock_quantity']);$p->set_backorders('no');}$p->set_menu_order($index);$p->set_category_ids([(int)$category['term_id']]);$p->set_sku('REF-'.$row['source_id']);$p->update_meta_data('_study_images',$row['images']);$p->update_meta_data('_study_tags',$row['tags']);$p->save();}
foreach(['cart'=>'Cart','checkout'=>'Checkout','my-account'=>'My Account'] as $slug=>$title){$page=get_page_by_path($slug);$id=$page?$page->ID:wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$title,'post_name'=>$slug,'post_content'=>'[woocommerce_'.str_replace('-','_',$slug).']']);update_option('woocommerce_'.str_replace('-','',$slug).'_page_id',$id);}
$parent=get_page_by_path('collections');$parent_id=$parent?$parent->ID:wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'Collections','post_name'=>'collections']);if(!get_page_by_path('collections/necklaces'))wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'Necklaces','post_name'=>'necklaces','post_parent'=>$parent_id]);
if(!get_option('study_shipping_configured')){$zone=new WC_Shipping_Zone();$zone->set_zone_name('Development — United States');$zone->add_location('US','country');$zone->save();$flat=$zone->add_shipping_method('flat_rate');update_option('woocommerce_flat_rate_'.$flat.'_settings',['enabled'=>'yes','title'=>'Standard shipping','tax_status'=>'none','cost'=>'5']);$free=$zone->add_shipping_method('free_shipping');update_option('woocommerce_free_shipping_'.$free.'_settings',['enabled'=>'yes','title'=>'Free shipping','requires'=>'min_amount','min_amount'=>'40']);update_option('study_shipping_configured',1);}
flush_rewrite_rules();echo 'Reference import complete: '.count($rows).' necklace records.';
